  "settings.paths.automatic": "Automatisch",
  "settings.paths.overrideNote": "Jede Zeile zeigt, wohin sie gerade zeigt. Nicht gesetzte Zeilen werden automatisch ermittelt, eine passende FAF_*-Umgebungsvariable schlägt das weiterhin. Eine Änderung greift sofort; vorhandene Inhalte werden nicht mitverschoben.",
  "settings.paths.gameInstall": "Spielinstallation",
