  "settings.game.cacheRollingBranchesHint": "Behält jeden gespielten Develop- und Beta-Build, damit deren Replays abspielbar bleiben.",
  "settings.game.experimentalBadge": "Experimentell",
  "settings.game.cacheRollingBranchesDocTitle": "Funktionsweise von Entwicklungszweig-Caching und Replay-Speicherung",
  "settings.game.cacheRollingBranchesDocOverview": "Entwicklungszweige wie FAF Develop und FAF Beta besitzen keine dauerhaften Versionsnummern auf dem Server. Sobald neue Commits bereitgestellt werden, werden ältere Builds überschrieben, wodurch ältere Replays asynchron werden oder abbrechen.",
  "settings.game.cacheRollingBranchesDocHowTitle": "Version-Snapshotting",
  "settings.game.cacheRollingBranchesDocHowDesc": "Wenn aktiviert, wird jeder gespielte Build anhand seines Git-Commit-SHA und Datei-Hash identifiziert und in einem lokalen Versionsmanifest erfasst.",
  "settings.game.cacheRollingBranchesDocReplayTitle": "Änderungen an Replay-Dateien",
  "settings.game.cacheRollingBranchesDocReplayDesc": "Lokal aufgezeichnete .fafreplay-Dateien werden in der JSON-Kopfzeile um git_sha, git_short_sha und build_signature ergänzt. Dadurch kann der Client beim Abspielen exakt die passende Version wiederherstellen, bleibt jedoch vollständig kompatibel mit anderen FAF-Clients.",
