  "settings.connectivity.connectivityAdapterHint": "Dynamisch nimmt den Adapter des Hosts: Go bei einer Lobby mit [go-adapter] im Titel, sonst Java. Gilt ab dem nächsten Spiel.",
  "settings.connectivity.hostAdapter": "Spiele hosten mit",
  "settings.connectivity.hostAdapterHint": "Mit Go bekommt dein Spieltitel [go-adapter]: Spieler mit Dynamisch in diesem Client treten dann von selbst mit Go bei, alle anderen müssen auf Go umstellen. Gilt ab dem nächsten Spiel.",
  "settings.connectivity.dynamic": "Dynamisch (folgt dem Host, empfohlen)",
  "settings.discord.richPresence": "Rich Presence",
  "settings.discord.richPresenceHint": "Das Spiel, das du hostest oder spielst, im Discord-Profil zeigen.",
  "settings.discord.disallowJoinsVia": "Beitritt über Discord verbieten",
  "settings.discord.disallowJoinsViaHint": "Status sichtbar lassen, aber den Beitritts-Button entfernen, damit niemand über Discord in deine Lobby kommt.",
  "settings.steam.presence": "Steam-Status",
  "settings.steam.presenceHint": "Während du in einem Spiel bist, zeigt Steam dich als Spieler von Forged Alliance und zählt die Stunden; der geöffnete Client zählt nicht. Steam muss laufen und Forged Alliance in deiner Steam-Bibliothek sein. Aus, bis du es einschaltest.",
  "settings.steam.confirmButton": "Einschalten",
  "settings.steam.confirmTitle": "Steam-Status einschalten?",
  "settings.steam.confirmBody": "Der Client lädt dann beim Spielen Valves nicht quelloffene Steamworks-Bibliothek. Sie teilt Steam mit, wann du auf FAF Forged Alliance spielst, und wir können nicht prüfen, was die Bibliothek sonst noch an Valve senden könnte.",
  "settings.steam.trustClosed": "Dafür muss der Client Valves Steamworks-Bibliothek laden, und die ist nicht quelloffen. Wir bestimmen, welche ihrer Funktionen wir aufrufen, und rufen nur drei auf (Start, Aufrechterhalten, Beenden), können aber nicht sehen oder prüfen, was die Bibliothek selbst tut oder an Valve sendet. Wer das einschaltet, vertraut Valve darin.",
  "settings.steam.trustCalls": "Der Client selbst teilt Steam nur mit, dass du Forged Alliance gestartet und beendet hast. Steam weiß dann, welches Konto von wann bis wann gespielt hat, und zeigt es deinen Freunden nach deinen eigenen Steam-Privatsphäre-Einstellungen. FAF ist ein eigener Client: Ohne diese Einstellung erfährt Steam nicht, wann du auf FAF spielst.",
  "settings.steam.trustTitle": "Was das sendet, und was wir nicht prüfen können",
