  "tournaments.console.tabArticles": "Artikel",
  "tournaments.console.siteAdminsHint": "Seitenadmins haben volle Kontrolle über jedes Turnier und diese Konsole. Der Zugang hängt an einem FAF-Konto: Man verknüpft es mit dem Master-Passwort, das auch nach dem Entfernen hier jederzeit neu verknüpft. Andere unten per FAF-Name hinzufügen.",
