  "tournaments.console.directorsHint": "Direktoren haben Organisatorrechte auf jedem offiziellen Turnier (nicht auf Community-Turnieren), sehen Entwürfe aller Turniere (ohne Rechte auf Community-Turnieren) und haben in dieser Konsole Anträge, Direktoren, Sperren, Logs, Archiv und Artikel.",
  "tournaments.console.directorsHint2": "Direktoren können Direktoren hinzufügen und entfernen, das Team verwaltet sich selbst. Jede Änderung wird mit Namen protokolliert, und der letzte Direktor kann nicht entfernt werden.",
  "tournaments.console.directorsNone": "Noch keine Direktoren.",
  "tournaments.console.makeDirector": "Zum Direktor machen",
